#[derive(Default)]
pub(super) struct MeshData {
    pub(super) vert: Vec<[f32; 3]>,
    pub(super) polynormal: Vec<[f32; 3]>,
    pub(super) polyvertadr: Vec<i32>,
    pub(super) polyvertnum: Vec<i32>,
    pub(super) polyvert: Vec<i32>,
    pub(super) polymapadr: Vec<i32>,
    pub(super) polymapnum: Vec<i32>,
    pub(super) polymap: Vec<i32>,
}

pub(super) struct WorldPose {
    pub(super) pos: Vec<[f32; 3]>,
    pub(super) rot: Vec<[f32; 9]>,
}

pub(super) struct Case {
    pub(super) name: String,
    pub(super) reference: String,
    pub(super) standalone: bool,
    pub(super) pair: [usize; 2],
    pub(super) geomtypes: Vec<i32>,
    pub(super) sizes: Vec<[f32; 3]>,
    pub(super) mesh: Option<MeshData>,
    pub(super) worlds: Vec<WorldPose>,
    /// 输入对齐口径：mjwarp f32 运动学（quat_to_matrix 三列路径）重算的世界位姿。
    pub(super) aligned: Vec<WorldPose>,
}

pub(super) fn floats(value: &Value) -> Vec<f32> {
    value
        .as_array()
        .expect("数值数组")
        .iter()
        .map(|item| item.as_f64().expect("数值") as f32)
        .collect()
}

pub(super) fn vec3(value: &Value) -> [f32; 3] {
    let values = floats(value);
    [values[0], values[1], values[2]]
}

pub(super) fn vec9(value: &Value) -> [f32; 9] {
    let mut out = [0.0_f32; 9];
    out.copy_from_slice(&floats(value));
    out
}

pub(super) fn cases() -> Vec<Case> {
    let value: Value = serde_json::from_str(CASE_DATA).expect("内嵌数据应为合法 JSON");
    value["cases"]
        .as_array()
        .expect("cases 数组")
        .iter()
        .map(|entry| {
            let mesh = entry.get("mesh").map(|mesh| MeshData {
                vert: floats(&mesh["vert"])
                    .chunks(3)
                    .map(|c| [c[0], c[1], c[2]])
                    .collect(),
                polynormal: floats(&mesh["polynormal"])
                    .chunks(3)
                    .map(|c| [c[0], c[1], c[2]])
                    .collect(),
                polyvertadr: floats(&mesh["polyvertadr"])
                    .iter()
                    .map(|&v| v as i32)
                    .collect(),
                polyvertnum: floats(&mesh["polyvertnum"])
                    .iter()
                    .map(|&v| v as i32)
                    .collect(),
                polyvert: floats(&mesh["polyvert"])
                    .iter()
                    .map(|&v| v as i32)
                    .collect(),
                polymapadr: floats(&mesh["polymapadr"])
                    .iter()
                    .map(|&v| v as i32)
                    .collect(),
                polymapnum: floats(&mesh["polymapnum"])
                    .iter()
                    .map(|&v| v as i32)
                    .collect(),
                polymap: floats(&mesh["polymap"]).iter().map(|&v| v as i32).collect(),
            });
            Case {
                name: entry["name"].as_str().expect("name").to_owned(),
                reference: entry["reference"].as_str().expect("reference").to_owned(),
                standalone: entry["standalone"].as_bool().expect("standalone"),
                pair: [
                    entry["pair"][0].as_u64().expect("pair0") as usize,
                    entry["pair"][1].as_u64().expect("pair1") as usize,
                ],
                geomtypes: entry["geoms"]
                    .as_array()
                    .expect("geoms")
                    .iter()
                    .map(|geom| geom["type"].as_i64().expect("type") as i32)
                    .collect(),
                sizes: entry["geoms"]
                    .as_array()
                    .expect("geoms")
                    .iter()
                    .map(|geom| vec3(&geom["size"]))
                    .collect(),
                mesh,
                worlds: entry["worlds"]
                    .as_array()
                    .expect("worlds")
                    .iter()
                    .map(|world| WorldPose {
                        pos: world["pos"]
                            .as_array()
                            .expect("pos")
                            .iter()
                            .map(vec3)
                            .collect(),
                        rot: world["rot"]
                            .as_array()
                            .expect("rot")
                            .iter()
                            .map(vec9)
                            .collect(),
                    })
                    .collect(),
                aligned: entry["aligned"]
                    .as_array()
                    .expect("aligned")
                    .iter()
                    .map(|world| WorldPose {
                        pos: world["pos"]
                            .as_array()
                            .expect("pos")
                            .iter()
                            .map(vec3)
                            .collect(),
                        rot: world["rot"]
                            .as_array()
                            .expect("rot")
                            .iter()
                            .map(vec9)
                            .collect(),
                    })
                    .collect(),
            }
        })
        .collect()
}

pub(super) fn root() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
}
